from collections import deque
jobs = {  # 작업: (읽는 표, 만드는 표)
    "ingest_log": ([], ["raw.app_log"]),
    "basis_click": (["raw.app_log"], ["basis.shop_click"]),
    "metric_act": (["basis.shop_click"], ["metric.shop_activation"]),
    "company_kpi": (["metric.shop_activation"], ["kpi.daily"]),
}
made_by = {t: j for j, (_, outs) in jobs.items() for t in outs}
deps = {j: sorted({made_by[t] for t in ins if t in made_by}) for j, (ins, _) in jobs.items()}
print("센서가 기다릴 작업:", deps)
down = {}
for j, ds in deps.items():
    for d in ds:
        down.setdefault(d, []).append(j)
q, seen = deque(["basis_click"]), []
while q:
    for n in down.get(q.popleft(), []):
        if n not in seen:
            seen.append(n); q.append(n)
print("basis_click 이 깨지면:", seen)
# 센서가 기다릴 작업: {'ingest_log': [], 'basis_click': ['ingest_log'], 'metric_act': ['basis_click'], 'company_kpi': ['metric_act']}
# basis_click 이 깨지면: ['metric_act', 'company_kpi']
